head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > changeCurrency]<br/>Body Column 의 ID 를 사용하여 특정 Body Column 의 dataType 속성을 화폐 단위값으로 설정합니다.",
    "validation" : [
        "columnId(필수) 파라미터로 dataType 속성을 설정할 Body Column 의 ID 를 설정할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'float' 를 설정하여 화폐 단위 dataType 속성값을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'number' 를 설정하여 화폐 단위 dataType 속성값을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'euro' 를 설정하여 화폐 단위 dataType 속성값을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'rupee' 를 설정하여 화폐 단위 dataType 속성값을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터로 'tenge' 를 설정하여 화폐 단위 dataType 속성값을 변경할 수 있어야 합니다.",
        "dataType(필수) 파라미터는 'float', 'number', 'euro', 'rupee', 'tenge' 값으로만 설정할 수 있으며, 5 개 값 이외의 값을 설정하면 메소드가 실행되지 않습니다.",
        "'text', 'date' 의 dataType 속성값은 changeCurrency() 메소드로 설정할 수 없습니다.",
        "displayFormat(선택) 파라미터로 화폐값이 표시되는 포맷을 '#', '0', ',', '.' 마스크 문자로 설정할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] Body Column col1~col4 는 dataType 미설정(기본 text), Row 0 원본 데이터는 모두 1234567\n[전제] 본 프로젝트 config.xml 에는 화폐 마스크 설정이 없어 displayFormat 없이는 메소드가 실행되지 않으므로, displayFormat 미지정 시 dataType 별 고정 마스크를 사용한다 (float/number: #,##0.00 / euro: #.###,00 / rupee: ##,##,###.00 / tenge: # ###,00)\n[절차] columnId + dataType 선택 후 changeCurrency 실행 (displayFormat 을 지정하면 고정 마스크 대신 그 값이 적용됨)\n[확인] 대상 Column 의 Row 0 셀 표시값이 선택한 화폐 포맷으로 바뀌는지 확인 (표시값이 변경 전과 같으면 메소드 미실행)"', '', 'label1');

    // dataList 생성 + 바인딩
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // 화폐 포맷 검증용 초기 데이터 설정
    dlt_bind.setJSON([
        { "col1": "1234567", "col2": "1234567", "col3": "1234567", "col4": "1234567" }
    ]);

    // 화폐 포맷 적용 후 값이 잘리지 않도록 Column 너비 자동 조정 (검증 대상 아닌 표시 편의용 고정 설정)
    let properties = { dataList: "data:dlt_bind", autoFit: "allColumn" };
    let cList = $c.gcm.createCList(properties);

    // target 생성 (기본 4컬럼 col1~col4)
    await $c.gcm.createBasicGridView(cList);
}



// Body Column ID 로 Row 0 셀의 표시값(DOM) 조회
scwin.getCellText = function (columnId) {
    let colIndex = Number(columnId.replace("col", "")) - 1;
    let objCell = document.querySelector("td[id*='target1_cell_0_" + colIndex + "']");

    return (objCell === null) ? "(셀 없음)" : objCell.textContent;
}



scwin.btn_changeCurrency_onclick = function () {
    let columnId = par_columnId.getValue();
    let dataType = par_dataType.getValue();
    let displayFormat = par_displayFormat.getValue();

    // displayFormat 미지정 시 config.xml 에 화폐 마스크가 없어 dataType 별 고정 마스크를 사용
    if (displayFormat === '') {
        let maskMap = { "float": "#,##0.00", "number": "#,##0.00", "euro": "#.###,00", "rupee": "##,##,###.00", "tenge": "# ###,00" };
        displayFormat = maskMap[dataType] || "#,##0.00";
    }

    // 변경 전 표시값
    let beforeText = scwin.getCellText(columnId);

    target1.changeCurrency(columnId, dataType, displayFormat);

    wf_body_bottom.getObj("scwin").setReturnValue("changeCurrency('" + columnId + "', '" + dataType + "', '" + displayFormat + "') | 변경 전 Row 0 표시값 : '" + beforeText + "' | 변경 후 Row 0 표시값 : '" + scwin.getCellText(columnId) + "'");
}



scwin.btn_checkDisplayValue_onclick = function () {
    let columnId = par_columnId.getValue();

    wf_body_bottom.getObj("scwin").setReturnValue("현재 " + columnId + " Row 0 표시값 : '" + scwin.getCellText(columnId) + "'");
}
